Ltac inl := apply L5K.In_of_mem; vm_compute; reflexivity.
Abbreviation reg i := (Z_to_bv 5 (Z.of_nat i)).
Abbreviation RSEGS := Asan.M.loaded_segments.
Section WithHeap.
Context {SCFG_P : ScfgP}.
Variables (L : asan_layout) (ar : asan_run) (C : asan_statics_cells) (HI : asan_iface).
Hypothesis LY : PMA.layout L C.
Hypothesis HIok : HAJ.asan_iface_okR L ar C SCFG HI.
Let LYa := PMA.ly_as0 L C LY.

Theorem reserveI_ok : PQATSCa.reserveI_spec L ar HI.
Proof.
  unfold PQATSCa.reserveI_spec, PQATSC.reserveI_specG.
  intros fx R M model K LB FF LK Aw cr sp r o n fb len v0 v1 HH AM K0 ENT FRM FRS SP16 A10 A11 Hn AO O8 ACC BIN BASE KONT.
  destruct ENT as (Rra & RAok & Rsp & Rgp & Rtp & ASTK & STKSH).
  pose proof RAok as (Hr1 & Hr2). pose proof ASTK as (A16 & SLO & SHI & SPT & SDEF & SUP).
  rewrite L5K.rl1 in Rra. rewrite L5K.rl2 in Rsp.
  change (PMSPA.pm_scr PQATSC.RSV_H) with 16384 in *.
  pose proof (HAJ.aior_wf _ _ _ _ _ HIok _ _ _ _ _ _ _ HH) as (WB & WF & FSAPP & FSCEIL & _).
  assert (SP0 : 0 <= ahl_ceil ar) by (unfold app_mem, FS_BYTES in *; lia).
  (* [comment removed for export] *)
  pose proof (PMASK.mach_vis L ar C HI LY HIok _ FF LK cr Aw M model HH BASE) as (VM0 & VSB & VUAR).
  destruct (PQAKR3.obj_pf L ar C HI LY HIok LB FF LK cr Aw M model o 32 HH AO O8 ltac:(lia) eq_refl) as ((OA1 & OA2 & OA3 & OA4) & OAV & ODEF & OAZ).
  specialize (OAZ ACC). change (32 / 8) with 4 in OAZ.
  pose proof (PQAKR3.stk_w_vis L ar C HI LY HIok LB FF LK cr Aw M model sp 16384 (sp - 112) 112 HH ASTK ltac:(lia) ltac:(lia) ltac:(lia)) as SW.
  set (H := ahid Aw model) in *. set (MV := mrestrict H M) in *.
  assert (WO : L5.writable RSEGS MV o 32).
  { apply (proj2 (L5A.writable_vis H M o 32 OAV ltac:(lia) ltac:(lia))). apply (L5C.writable_of_defined RSEGS M o 32 ODEF); lia. }
  pose proof BIN as ((Bfb & Bfr & Blen & Bt0 & B16 & B24 & Ble & Bv0 & Bv1) & _ & _). cbn [L5.bo_fb L5.bo_len L5.bo_st] in Bfb, Bfr, Blen, Bt0, B16, B24, Ble.
  assert (VFB : L5.u8_at RSEGS MV o fb) by (apply (proj2 (L5A.u8_at_vis H M o fb (L5A.avis_sub H o 32 o 1 OAV ltac:(lia) ltac:(lia)) ltac:(lia) ltac:(lia))); exact Bfb).
  assert (AL16 : PQATCP1.aligned sp 16) by (unfold PQATCP1.aligned; exact SP16).
  assert (AL8 : PQATCP1.aligned o 8) by (unfold PQATCP1.aligned; exact O8).
  LeanFeed.pfeed ident:(P) (PQATCP1.qtvI_conc fx R MV (fun j => match j with 2%nat => sp | 33%nat => o | 34%nat => n | 38%nat => fb | _ => 0 end)) ltac:(first [assumption | exact Rsp | exact A10 | exact A11 | lia]).
  destruct P as (fx1 & R1 & M1v & MG1 & _ & FRZ1 & MS1 & KS1 & _).
  assert (R1ra : getr R1 (reg 1) = Z_to_bv 64 r) by (rewrite (KS1 1%nat) by inl; exact Rra).
  pose proof (PMK.ret_to RSEGS fx1 R1 M1v 0xca610 W_ca5c0 r F_ca5c0 eq_refl D_ca5c0 R1ra ltac:(lia) Hr2) as MS2.
  unfold PMSPA.cfg.
  apply (L5SAR.apiece L ar C HI LYa HIok LB FF LK cr Aw M model fx fx1 R 0xca420 R1 r M1v (fun a => sp - 104 <= a < sp - 104 + 104) K HH AM).
  { eapply msteps_trans; [exact MS1| exact MS2]. }
  { exact MG1. }
  { intros a Ha N. apply FRZ1; [exact Ha| exact N]. }
  { intros a Ha Wa. split; [| lia]. unfold aclientw, aclient_g. right; left. split; [lia| intros X; lia]. }
  intros M1 model1 HH1 AM1 MRT1 HID1 VIS1 MGM1 FR1 VV1.
  (* [comment removed for export] *)
  assert (EK0 : L5SAR.ek L ar LB FF sp 16384 [] M M1).
  { apply (L5SAR.ek_piece L ar LB FF sp 16384 [] M M1 (fun a => sp - 104 <= a < sp - 104 + 104)).
    { intros a Ha N. apply FR1; [exact Ha| exact N]. }
    intros a Ha Hc Ho X.
    destruct (L5SAR.aclient_cases L ar C HI LYa HIok LB FF LK cr Aw M (vml_of model) sp 16384 a HH SPT Hc) as [(Y1 & Y2)|Y]; [apply Y2; lia| lia]. }
  apply (KONT fx1 R1 M1 model1 LK).
  - apply L5SAR.preserved_by_index. intros k Hk. apply KS1. unfold L5SAR.cs_all in Hk. repeat (destruct Hk as [<-|Hk]; [inl|]). destruct Hk.
  - (* [comment removed for export] *)
    assert (AGo : L5C.agree_on M M1 o 32) by (intros i Hi; apply FR1; lia).
    destruct BIN as (BIG & Bv0' & Bv1'). split; [exact (L5C.big_at_agree RSEGS M M1 o _ AGo ltac:(lia) ltac:(lia) BIG)| split; [exact Bv0'| exact Bv1']].
  - apply (L5SAR.ahpres_of L ar LB FF sp 16384 [] M M1 EK0).
    + intros i Hi. apply MGM1. apply SDEF. exact Hi.
    + apply (L5SAR.dk_grows L ar LB FF sp 16384 M M1 MGM1).
  - exact MRT1.
  - intros x Hx. exact Hx.
  - exact AM1.
  - exact HH1.
Qed.
