  GM BX1 M1 model1 LK1 Aw1 cr1 ->
  (forall a, 0 <= a < 2 ^ 64 -> ~ Wp a -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
  (forall a, Wp a -> (sp - SCR <= a < sp) \/ (F <= a < F + 128) \/ (F / 8 + SB <= a < F / 8 + SB + 16)) ->
  L5SAR.ek L ar (BX1 ++ LBX) FF sp SCR [] M1 M3.
